\title{Uniqueness of the Critical Two-Point Augmentation \\ of a 27-Point Unit-Distance Graph}
\author{Aristotle}
\date{July 2, 2026}

\begin{document}

\begin{abstract}
The study of the fractional chromatic number of the Euclidean plane proceeds through finite unit-distance graphs whose independence ratios yield lower bounds. A striking phenomenon in this circle of ideas is that a certain $27$-point planar unit-distance configuration $G_{27}$, upon the addition of a specific pair of points, becomes a $29$-point configuration $G_{29}$ whose geometric fractional chromatic number is strictly greater than $4$. We isolate and rigorously establish the arithmetic mechanism driving this phenomenon and prove its minimality. The mechanism is a threshold crossing of the independence ratio $\alpha/m$ against the critical value $1/4$: with independence number pinned at $\alpha = 7$, the ratio equals $7/27 > 1/4$ before augmentation, exactly $7/28 = 1/4$ after a single added point, and $7/29 < 1/4$ after two. We show that $\alpha/m < 1/4 \iff 4\alpha < m$; that for any base graph on $n$ vertices with independence number $a$ and $n \le 4a$, the least number of vertices one must add---while preserving the independence number---to force the ratio strictly below $1/4$ is exactly $4a - n + 1$; and that this specializes to $2$ for $G_{27}$. On the graph side we prove that augmentation can only increase the independence number, whence an augmentation preserving it is precisely a critical one. Combining these yields a dichotomy that reduces the open geometric uniqueness conjecture to a single sharply posed realizability question.
\end{abstract}

\maketitle

\section{Introduction}

The chromatic number of the plane, $\chi(\mathbb{R}^2)$, is the least number of colors needed to color the points of the Euclidean plane so that no two points at distance exactly $1$ receive the same color; it is known that $5 \le \chi(\mathbb{R}^2) \le 7$. A quantitative relaxation, the \emph{fractional chromatic number} $\chi_f(\mathbb{R}^2)$, assigns to each point a measurable weight of colors subject to the same unit-distance constraint and minimizes the total color mass. Lower bounds are obtained from finite \emph{unit-distance graphs}.

A unit-distance graph is a finite simple graph $G = (V,E)$ with an injection $V \hookrightarrow \mathbb{R}^2$ such that $\{u,v\} \in E$ iff the images are at Euclidean distance exactly $1$. Since any valid coloring of the plane restricts to one of $G$, we have $\chi_f(\mathbb{R}^2) \ge \chi_f(G)$.

A distinguished $27$-vertex planar unit-distance graph $G_{27}$ has the property that a specific two-point augmentation yields a $29$-vertex graph $G_{29}$ with $\chi_f(G_{29}) > 4$. The \emph{critical augmentation conjecture} asserts that, up to Euclidean isometry, this two-vertex augmentation is the unique way to add two vertices to $G_{27}$ so that the result has geometric fractional chromatic number strictly greater than $4$. This paper isolates and fully proves the combinatorial core on which any realization must rest, and makes precise the geometric content that remains open.

\section{Definitions and preliminaries}

Throughout, graphs are finite and simple.

\begin{definition}[Independence number]
A set $S \subseteq V$ is \emph{independent} if no two members are adjacent. The \emph{independence number} $\alpha(G)$ is the maximum size of an independent set.
\end{definition}

\begin{definition}[Independence ratio]
The \emph{independence ratio} of a graph on $m$ vertices with independence number $\alpha$ is $\alpha/m$.
\end{definition}

\begin{definition}[Fractional chromatic number]
A \emph{fractional coloring} assigns each independent set $S$ a weight $w(S) \ge 0$ so that $\sum_{S \ni v} w(S) \ge 1$ for every vertex $v$. Then $\chi_f(G) = \min \sum_S w(S)$, a rational number.
\end{definition}

\begin{lemma}[Ratio bound]\label{lem:ratio}
For any graph $G$ on $m$ vertices with independence number $\alpha$, $\chi_f(G) \ge m/\alpha$.
\end{lemma}
\begin{proof}
Each independent set covers at most $\alpha$ vertices. Summing $\sum_{S \ni v} w(S) \ge 1$ over all $m$ vertices and exchanging summation order, $\alpha \sum_S w(S) \ge m$, so $\sum_S w(S) \ge m/\alpha$.
\end{proof}

\begin{corollary}[Forcing above 4]\label{cor:force}
If $\alpha/m < 1/4$ then $\chi_f(G) > 4$.
\end{corollary}
\begin{proof}
By Lemma~\ref{lem:ratio}, $\chi_f(G) \ge m/\alpha = (\alpha/m)^{-1} > 4$.
\end{proof}

\begin{definition}[Augmentation]
Let $G$ be a graph on $W$ and $f : V \hookrightarrow W$ injective. The induced subgraph on $f(V)$, transported to $V$, is $f^{*}G$: vertices $u,v$ are adjacent iff $f(u),f(v)$ are adjacent in $G$. Then $G$ is an \emph{augmentation} of $f^{*}G$, obtained by adding the vertices of $W \setminus f(V)$ and their incident edges.
\end{definition}

\section{The arithmetic core}

\begin{theorem}[Threshold identity]\label{thm:threshold}
For natural numbers $a,m$ with $m > 0$, $\ \dfrac{a}{m} < \dfrac14 \iff 4a < m$.
\end{theorem}
\begin{proof}
Since $m > 0$, multiplying $a/m < 1/4$ by the positive quantity $4m$ gives the equivalent integer inequality $4a < m$; both directions coincide as all quantities are integers cast into $\mathbb{Q}$.
\end{proof}

\begin{theorem}[Minimal augmentation, general form]\label{thm:min}
Let $a,n \in \mathbb{N}$ with $n > 0$ and $n \le 4a$. Then the set $\{\, k \in \mathbb{N} : a/(n+k) < 1/4 \,\}$ has least element $k_{\min} = 4a - n + 1$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:threshold}, $a/(n+k) < 1/4 \iff 4a < n + k \iff k \ge 4a - n + 1$. For $k_{\min}$ we have $n + k_{\min} = 4a + 1 > 4a$, so $k_{\min}$ is in the set; and any element $k$ satisfies $k \ge 4a - n + 1 = k_{\min}$. The hypothesis $n \le 4a$ makes $k_{\min} \ge 1$ well-defined in $\mathbb{N}$.
\end{proof}

\begin{theorem}[$G_{27}$ specialization]\label{thm:g27}
With $a = 7$, $n = 27$,
\[ \frac{7}{27} > \frac14, \qquad \frac{7}{28} = \frac14, \qquad \frac{7}{29} < \frac14, \]
and the least number of added vertices forcing the ratio strictly below $1/4$ is $4\cdot 7 - 27 + 1 = 2$.
\end{theorem}
\begin{proof}
The three numerical statements are direct rational computations. Minimality is Theorem~\ref{thm:min} at $a = 7$, $n = 27$, using $27 \le 28 = 4\cdot 7$.
\end{proof}

The exact equality $7/28 = 1/4$ is essential: a single added vertex leaves the ratio exactly at the boundary, never strictly below, so one vertex can never force $\chi_f > 4$ through the ratio bound. This is why the magic number is $2$, not $1$.

\section{The graph-theoretic core}

\begin{theorem}[Monotonicity under augmentation]\label{thm:mono}
Let $G$ be a finite graph on $W$ and $f : V \hookrightarrow W$ injective. Then $\alpha(f^{*}G) \le \alpha(G)$: adding vertices can only enlarge, never shrink, the maximum independent set.
\end{theorem}
\begin{proof}
Let $t \subseteq V$ be a maximum independent set of $f^{*}G$, so $|t| = \alpha(f^{*}G)$. Since $f$ is injective and $u \sim_{f^{*}G} v \iff f(u) \sim_G f(v)$, the image $f(t)$ is independent in $G$ with $|f(t)| = |t|$. Hence $\alpha(f^{*}G) = |t| = |f(t)| \le \alpha(G)$. Injectivity is essential; a non-injective map could collapse distinct independent vertices.
\end{proof}

\begin{definition}[Critical augmentation]
An augmentation $G$ of a base $H = f^{*}G$ is \emph{critical} if $\alpha(G) = \alpha(H)$.
\end{definition}

By Theorem~\ref{thm:mono} the only alternative is a strict increase $\alpha(G) > \alpha(H)$; criticality is precisely the equality case, keeping the numerator of the independence ratio fixed while the denominator grows.

\begin{theorem}[Critical-augmentation dichotomy]\label{thm:dich}
Let $H$ have $n = 27$ vertices with $\alpha(H) = 7$, and let $G$ be a critical two-vertex augmentation of $H$ (so $|V(G)| = 29$, $\alpha(G) = 7$). Then the base is not forced above the threshold, $7/27 > 1/4$ giving $\chi_f(H) \ge 27/7 < 4$; while $G$ is forced strictly above, $7/29 < 1/4$ giving $\chi_f(G) \ge 29/7 > 4$.
\end{theorem}
\begin{proof}
For $H$: $7/27 > 1/4$ by Theorem~\ref{thm:g27}, and $\chi_f(H) \ge 27/7 = 3.857\ldots \le 4$. For $G$: criticality keeps $\alpha(G) = 7$ with $29$ vertices; then $7/29 < 1/4$ (Theorem~\ref{thm:g27}) and Corollary~\ref{cor:force} give $\chi_f(G) > 4$.
\end{proof}

\section{Discussion}

The chief consequence is diagnostic: the rarity of fractional-chromatic-raising augmentations of $G_{27}$ is a sharp counting threshold gated by the exact equality $7/28 = 1/4$. What remains open is geometric realizability---whether two real points can be added to $G_{27}$ forming the requisite unit distances without enlarging the maximum independent set, and whether such a placement is unique up to Euclidean isometry. The dichotomy is sharp on both ends, and no theorem is vacuous: Theorem~\ref{thm:threshold} requires $m > 0$; Theorem~\ref{thm:min} requires $n \le 4a$; Theorem~\ref{thm:mono} uses injectivity essentially. Theorem~\ref{thm:min} is uniform, so the ``two'' of $G_{27}$ is one value of the affine family $4a - n + 1$.

\section{Future directions}

\begin{conjecture}[Rigidity of independence-preserving extensions]
Among all ways of adding two points to a $27$-point planar unit-distance configuration of independence number seven, only finitely many (up to Euclidean isometry) keep the independence number equal to seven, and generically none do.
\end{conjecture}

\begin{conjecture}[No one-point shortcut]
No addition of a single point to a $27$-point planar unit-distance configuration of independence number seven can force the geometric fractional chromatic number above four, since a single added point leaves the independence ratio at exactly $1/4$.
\end{conjecture}

\begin{conjecture}[Minimal-crossing law]
For every base configuration of $n$ points whose unit-distance graph has independence number $a$ with $n \le 4a$, the least number of added points forcing the geometric fractional chromatic number above four---while preserving the independence number---is exactly $4a - n + 1$, realized geometrically for infinitely many pairs $(a,n)$.
\end{conjecture}

\section{Conclusion}

We distilled the $G_{27} \to G_{29}$ phenomenon to an independence ratio crossing $1/4$, governed by $\alpha/m < 1/4 \iff 4\alpha < m$, with minimal added vertices $4a - n + 1 = 2$ for $G_{27}$; and we showed criticality is exactly independence-preservation. The remaining open content is thereby reduced to a single well-posed rigidity question.

